<template><view class="page"><text class="title">家庭成员</text><text class="sub">一起照护王秀兰，共享必要的照护信息</text><view v-for="m in members" :key="m.id" class="card member" @tap="manage(m)"><view class="avatar">{{m.name.slice(-1)}}</view><view class="main"><text class="name">{{m.name}} · {{m.relation}}</text><text class="meta">{{m.phone}} · {{m.role}}</text></view><text class="arrow">→</text></view><button class="add" @tap="invite">+ 邀请家庭成员</button></view></template><script>import {familyMembers} from '@/store/mock';export default{data(){return{members:[]}},onShow(){const invited=uni.getStorageSync('invited_members')||[];this.members=[...familyMembers,...invited.map((m,i)=>({...m,id:'local-'+i}))]},methods:{invite(){uni.navigateTo({url:'/pages/family/member-invite/index'})},manage(m){uni.showActionSheet({itemList:['设为主要照护人','设为紧急联系人','移除成员'],success:r=>uni.showToast({title:r.tapIndex===2?'测试成员已移除':'角色设置成功',icon:'none'})})}}}</script><style scoped>.page{min-height:100vh;padding:30rpx;background:#f6f7f3}.title{display:block;font-size:40rpx;font-weight:900;color:#2d4338}.sub{display:block;margin:10rpx 0 26rpx;color:#7b857f;font-size:21rpx}.card{background:#fff;border-radius:26rpx}.member{margin-bottom:16rpx;padding:24rpx;display:flex;align-items:center}.avatar{width:72rpx;height:72rpx;border-radius:22rpx;background:#dce9df;display:flex;align-items:center;justify-content:center;margin-right:18rpx;color:#326a53;font-weight:900}.main{flex:1}.name,.meta{display:block}.name{font-size:26rpx;font-weight:900}.meta{margin-top:6rpx;font-size:20rpx;color:#7c867f}.arrow{color:#959c97}.add{margin-top:8rpx;background:#326a53;color:#fff;border-radius:20rpx}</style>